  await new Promise((resolve4) => server2.listen(0, "127.0.0.1", resolve4));
  const port = server2.address().port;
  timers.idle = setTimeout(close, IDLE_MS);
  timers.max = setTimeout(close, MAX_MS);
  active = { server: server2, close };
