import * as fs23 from "fs";
import * as path23 from "path";
init_cli();
init_session();
function querier(targetOrg) {
  return {
    soql: (q, options) => runSoqlQuery(q, targetOrg, options),
    tooling: (q) => runToolingQuery(q, targetOrg)
  };
}
function compiledSchema(targetOrg) {
  return createCompiledSchemaSource({ org: querier(targetOrg), getSession: () => createDeviceSession(targetOrg) });
}
function telemetryFields(targetOrg) {
  return async () => {
    const result2 = await cachedDescribeSObject("DeviceSyncSummary", targetOrg);
    return new Set(result2.success ? (result2.data?.fields ?? []).map((f) => f.name) : []);
  };
}
function text10(body) {
  return { content: [{ type: "text", text: body }] };
}
function failure2(title, e) {
  return text10(`# ${title}

${e instanceof Error ? e.message : String(e)}`);
}
var targetOrgParam = external_exports.string().optional().describe("Optional: org alias/username for configuration reads. Uses current target org if not specified.");
var countAsOrgParam = external_exports.string().optional().describe(
  "Optional: org alias authenticated AS the persona user, used for the COUNT() queries so record sharing matches the device exactly. Defaults to the target org (the connected user's visibility, typically an admin)."
);
function register23(server2) {
  server2.tool(
    "profile_sync_volume",
    "Predict how much data the LSC mobile app will sync for specific users, before any device is involved. Resolves each user's DB Schema records (profile/permission set), substitutes WhereSoql tags ({USER.ID}, {USER.TERRITORY}, {ACCOUNT.IDS}, {OT2A.OBJ.IDS}, ...) per territory exactly as the app does, and runs COUNT() queries. Returns predicted records per table, estimated device SOQL request counts, and filters that fail to execute. Read-only; safe in production.",
    {
      users: external_exports.array(external_exports.string()).min(1).describe("Usernames or User Ids of representative field users"),
      territory: external_exports.string().optional().describe("Optional: territory name or Id to profile. Default: each of the user's territories in the active model (up to 5)."),
      idsPerQuery: external_exports.number().int().min(10).max(400).optional().describe("Optional: ids inlined per COUNT() query for {ACCOUNT.IDS}/{OT2A.OBJ.IDS} filters (default 200)"),
      targetOrg: targetOrgParam,
      countAsOrg: countAsOrgParam
    },
    async ({ users, territory, idsPerQuery, targetOrg, countAsOrg }) => {
      const validation = await validateOrgConnection();
      const effectiveOrg = targetOrg || validation.targetOrg;
      if (!effectiveOrg) return text10(`# Cannot Profile Sync Volume

${validation.error}`);
      try {
        const volumes = await profileUsers2(querier(effectiveOrg), querier(countAsOrg || effectiveOrg), users, {
          territory,
          compiledSchema: compiledSchema(effectiveOrg),
          ...idsPerQuery ? { idsPerQuery } : {}
        });
        let report = `# Predicted Mobile Sync Volume

**Org:** ${effectiveOrg}${countAsOrg ? ` (counts as ${countAsOrg})` : ""}

`;
        report += renderVolumes(volumes);
        report += `---

Counts are for an initial (full) sync. Without \`countAsOrg\`, counts use the connected user's record visibility, which can exceed what the field user can see.
`;
        return text10(report);
      } catch (e) {
        return failure2("Sync Volume Profiling Failed", e);
      }
    }
  );
  server2.tool(
    "analyze_sync_telemetry",
    "Analyze real-device sync performance from DeviceSyncSummary records uploaded by the LSC iOS app after every sync. Reports p50/p90/p95/max for initial and delta sync duration, download/upload phases, metadata cache download, records downloaded, device DB size, failure rate, and breakdowns by network and app version, plus the slowest syncs. Read-only; safe in production.",
    {
      days: external_exports.number().int().min(1).max(365).optional().default(30).describe("Look-back window in days (default 30)"),
      users: external_exports.array(external_exports.string()).optional().describe("Optional: restrict to these usernames"),
      profileName: external_exports.string().optional().describe("Optional: restrict to users with this profile name"),
      targetOrg: targetOrgParam
    },
    async ({ days, users, profileName: profileName3, targetOrg }) => {
      const validation = await validateOrgConnection();
      const effectiveOrg = targetOrg || validation.targetOrg;
      if (!effectiveOrg) return text10(`# Cannot Analyze Sync Telemetry

${validation.error}`);
      try {
        const { summary } = await loadTelemetry(querier(effectiveOrg), telemetryFields(effectiveOrg), {
          days,
          usernames: users,
          profileName: profileName3
        });
        let report = `# Mobile Sync Telemetry

**Org:** ${effectiveOrg}
`;
        if (users?.length) report += `**Users:** ${users.join(", ")}
`;
        if (profileName3) report += `**Profile:** ${profileName3}
`;
        report += "\n";
        report += summary.samples === 0 ? `No DeviceSyncSummary records in the last ${days} day(s) for this filter.
` : renderTelemetry(summary, days);
        return text10(report);
      } catch (e) {
        return failure2("Sync Telemetry Analysis Failed", e);
      }
    }
  );
  server2.tool(
    "run_perf_assessment",
    "Run an LSC performance assessment against an NFR profile (YAML): for each persona, predicts sync volume (profile_sync_volume) and summarizes field telemetry (analyze_sync_telemetry), then evaluates every metric against the profile's warn/fail thresholds and reports pass/warn/fail with the user, territory, or table that drove each result. Optionally writes the full result as JSON for CI or archiving. Read-only against the org.",
    {
      profilePath: external_exports.string().optional().describe("Path to an NFR profile YAML file"),
      profileYaml: external_exports.string().optional().describe("Inline NFR profile YAML (alternative to profilePath)"),
      outputPath: external_exports.string().optional().describe("Optional: write the full result as JSON to this path"),
      targetOrg: targetOrgParam,
      countAsOrg: countAsOrgParam
    },
    async ({ profilePath, profileYaml, outputPath, targetOrg, countAsOrg }) => {
      if (!profilePath && !profileYaml) {
        return text10("# Missing NFR Profile\n\nProvide `profilePath` or `profileYaml`. See the `lsc-performance-validation` skill for the format.");
      }
      let profile;
      try {
        profile = profilePath ? loadNfrProfile(profilePath) : parseNfrProfile(profileYaml);
      } catch (e) {
        return failure2("Invalid NFR Profile", e);
      }
      const validation = await validateOrgConnection();
      const effectiveOrg = targetOrg || validation.targetOrg;
      if (!effectiveOrg) return text10(`# Cannot Run Assessment

${validation.error}`);
      try {
        const result2 = await runAssessment(
          profile,
          effectiveOrg,
          querier(effectiveOrg),
          querier(countAsOrg || effectiveOrg),
          telemetryFields(effectiveOrg),
          { compiledSchema: compiledSchema(effectiveOrg) }
        );
        let report = renderAssessment(result2, profile.telemetry?.days ?? DEFAULT_TELEMETRY_DAYS);
        if (outputPath) {
          const resolved = path23.resolve(outputPath);
          fs23.mkdirSync(path23.dirname(resolved), { recursive: true });
          fs23.writeFileSync(resolved, JSON.stringify(result2, null, 2));
          report += `
Full result written to \`${resolved}\`.
`;
        }
        return text10(report);
      } catch (e) {
        return failure2("Performance Assessment Failed", e);
      }
    }
  );
}

